package com.bautruc.ecommerce.order.api;
import com.bautruc.ecommerce.common.logging.LogContext;import com.bautruc.ecommerce.common.response.*;import com.bautruc.ecommerce.common.security.*;import com.bautruc.ecommerce.common.time.BusinessClock;import com.bautruc.ecommerce.order.api.response.*;import com.bautruc.ecommerce.order.application.OrderQueryService;import org.springframework.security.access.AccessDeniedException;import org.springframework.web.bind.annotation.*;
@RestController public class MyOrderController{private final OrderQueryService orders;private final CurrentUserProvider current;private final BusinessClock clock;public MyOrderController(OrderQueryService o,CurrentUserProvider c,BusinessClock b){orders=o;current=c;clock=b;}@GetMapping("/api/v1/me/orders")public ApiResponse<PageResponse<OrderSummaryResponse>> list(@RequestParam(required=false)Integer page,@RequestParam(required=false)Integer size){return ok(PageResponse.from(orders.mine(user(),page,size)));}@GetMapping("/api/v1/me/orders/{id}")public ApiResponse<OrderDetailResponse> detail(@PathVariable Long id){return ok(orders.mineDetail(user(),id));}private Long user(){return current.currentUser().orElseThrow(()->new AccessDeniedException("Authentication required")).userId();}private <T>ApiResponse<T>ok(T d){return ApiResponse.success(d,null,clock.businessNow().toOffsetDateTime(),LogContext.currentCorrelationId());}}
